// Horspool's Algorithm
// O(nm)
// n: length of text
// m: length of pattern
// return: position of first occurrence of pattern in text
// if no occurrence, return -1
int horspool(string text, string pattern) {
    int n = text.size(), m = pattern.size();
    vector<int> shift(256, m);
    rep(i, m - 1) shift[pattern[i]] = m - i - 1;
    int i = m - 1;
    while (i < n) {
        int j = m - 1;
        while (j >= 0 && text[i] == pattern[j]) {
            i--;
            j--;
        }
        if (j == -1) return i + 1;
        i += shift[text[i]];
    }
    return -1;
}

