char s1[20], s2[20];
int dp[20][20];

int main() {
	int T;
	scanf("%d", &T);
	while (T--) {
		scanf("%s%s", s1, s2);
		int len1 = strlen(s1), len2 = strlen(s2);
		memset(dp, 0, sizeof(dp));
		for (int i = 1; i <= len1; i++) {
			for (int j = 1; j <= len2; j++) {
				if (s1[i-1] == s2[j-1]) {
					dp[i][j] = dp[i-1][j-1] + 1;
				} else {
					dp[i][j] = std::max(dp[i-1][j], dp[i][j-1]);
				}
			}
		}
		printf(" %d\n", dp[len1][len2]);
	}
	return 0;
}

