const int N = 1e5 + 10;

int n;
int q[N];

void bubble_sort()
{
    for (int i = 0; i < n - 1; i ++ )
        for (int j = 0; j < n - i - 1; j ++ )
            if (q[j] > q[j + 1])
                swap(q[j], q[j + 1]);
}

int main()
{
    scanf("%d", &n);
    for (int i = 0; i < n; i ++ ) scanf("%d", &q[i]);

    bubble_sort();

    for (int i = 0; i < n; i ++ ) printf("%d ", q[i]);

    return 0;
}

